# 큐보 2권 볼링머신(교재 100~106쪽) — 조립 프로그램(asmlib)으로 만든다.
# 순서대로 만든다: 1단계 → 확인 → 2단계 → 확인 …  (뒤에서부터 만들거나 중간부터 시작하지 않는다)
# 각 단계: 교재 그림을 왼쪽→오른쪽, 위→아래로 읽고(부품·초록 원·화살표), get_step_context 로 직전 상태(쓴 부품·남은 부품·빈 구멍)를 본 뒤 적는다.
# 교재 LIST(부품 목록, 26개 종류):
#   2단블록 14
#   3단블록 14
#   15프레임 4
#   17프레임 4
#   19프레임 2
#   29프레임 5
#   215프레임 2
#   35프레임 2
#   37프레임 6
#   39프레임 4
#   315프레임 6
#   59프레임 3
#   515프레임 2
#   713프레임 2
#   135도 프레임 4
#   리벳 66
#   부시 2
#   T축 4
#   2열브라켓 4
#   큰기어 4
#   DC모터 2
#   메인보드 1
#   리모컨 1
#   중간바퀴 2
#   너트 12
#   8볼트 12
import json, os, sys
import numpy as np
from asmlib import *

A = Asm("cubo-2-bowling", "볼링머신", "교재 100~106쪽 · 볼링머신 (1~37단계)", camera={"target": [60, 20, 0], "radius": 380, "theta": 0.9, "phi": 1.0},
        listNote="만드는 중 — 단계가 끝나기 전까지 LIST 개수는 안 맞는 것이 정상", guideMode="mates")   # 연결점은 부품에 붙어 있고 결합할 자리일 때만 보인다(맞물림 방식, 사용자 지시 2026-10-04)
RELOCK = True  # 2026-10-25 볼링머신: 옮겨진 부품(move_made)을 host 로 잠그는 기록이 빌드마다 결과를 뒤집어(21~26번) 항상 새로 계산한다 — "--relock" in sys.argv   # 잠금 기록을 새로 만들 때(수정 지시는 이번 빌드에서 무시한다)
if not RELOCK: A.load_fixes("bowling_fixes.json")   # 관리자 수정 지시(앞 단계 수정 → 뒤 단계가 따라온다). 파일이 없으면 아무 일도 안 한다
A.load_links("bowling_links.json", relock=RELOCK)   # 좌표로 쓴 결합·절대 좌표로 놓은 판을 이름으로 잠가 두는 기록
UP = (0, 1, 0)

# 쪽 표: 100쪽 완성품·LIST·1~2 / 101쪽 3~8 / 102쪽 9~14 / 103쪽 15~20 / 104쪽 21~26 / 105쪽 27~32 / 106쪽 33~37+완성 / 107쪽 작동 방법(단계 아님)
_PAGE = {**{n: 100 for n in (1, 2)}, **{n: 101 for n in range(3, 9)}, **{n: 102 for n in range(9, 15)}, **{n: 103 for n in range(15, 21)}, **{n: 104 for n in range(21, 27)},
         **{n: 105 for n in range(27, 33)}, **{n: 106 for n in range(33, 38)}}
SKEL = [A.step("[교재 %d] (작성 전) 교재 %d쪽 — 번호만 등록한 뼈대. 번호 작업 때 채운다." % (_n, _PAGE[_n]), noPart=True) for _n in range(1, 38)]
for _k in range(1, 38): A.steps[_k - 1].cam = (-0.79, 0.95, False, None, None, None); A.steps[_k - 1].camSrc = "guess"

# 구멍·돌기는 이름(면 +축, 열·줄)으로 말한다(안내서 3-1절). 번호를 모르면 get_part_faces / get_step_context 로 본다.

# ── 창고 정리(04, 2026-10-25): 교재 100~106쪽을 번호 순서대로 훑어 정했다. 번호표로 확인: 6(3 + 5) · 12(6 + 11) · 15(12 + 14) · 18(16 + 17) · 23(20 + 22) · 26(23 + 25) · 30(26 + 29) · 33(31 + 32) · 34(15 + 33)
#   "7~9번까지 2개 만들기"(9번)·"16~33번까지 2개 만들기"(33번) 표시가 있다. 1~8번만 정했다(나머지는 번호 작업 때 같은 방법으로 정한다).
#   1~3 : 713프레임 둘+29프레임 한 세트(창고 1) / 4~5 : 검은 판 둘+블록 새 세트(창고 2) / 6 : 3 + 5 합침(작은 번호 창고 1) / 7~11 : 빨간 막대·검은 판·흰 판·브라켓 세트(창고 2) / 12·15 : 합치기(창고 1)
#   13~14 : 7~9번 둘째 벌(창고 2) / 16~33 : 모터·기어 팔 세트를 둘 만든다(창고 2 = 몸통, 창고 3 = 곁가지: 17·21·24·27·32) / 34~37 : 창고 1 에서 합쳐 마무리
_SLOT_BW = {1: 1, 2: 1, 3: 1, 4: 2, 5: 2, 6: 1, 7: 2, 8: 2, 9: 2, 10: 2, 11: 2, 12: 1, 13: 2, 14: 2, 15: 1, 16: 2, 17: 3, 18: 2, 19: 2, 20: 2, 21: 3, 22: 3, 23: 2, 24: 3, 25: 3, 26: 2,
            27: 3, 28: 3, 29: 3, 30: 2, 31: 2, 32: 3, 33: 2, 34: 1, 35: 1, 36: 1, 37: 1}
for _i, _sl in _SLOT_BW.items(): A.steps[_i - 1].kw["slot"] = _sl
_HIST_BW = {4: "📦 713프레임 세트(1~3번)를 창고 1에 두고, 창고 2에서 검은 판 둘+블록 세트(4~5번)를 새로 시작",
            6: "창고 2의 세트(5번)를 가져와 창고 1의 3번 세트와 합쳐요 — 번호표 '3 + 5', 번호가 작은 창고 1 에서 합친다",
            7: "📦 합친 세트(6번)를 창고 1에 두고, 창고 2에서 빨간 막대+검은 판+흰 판 세트(7~9번)를 새로 시작",
            12: "창고 2의 세트(11번)를 가져와 창고 1의 6번 세트와 합쳐요 — 번호표 '6 + 11'",
            13: "📦 합친 세트(12번)를 창고 1에 두고, 창고 2에서 7~9번 둘째 벌(13~14번)을 새로 시작",
            15: "창고 2의 세트(14번)를 가져와 창고 1의 12번 세트와 합쳐요 — 번호표 '12 + 14'",
            16: "📦 합친 세트(15번)를 창고 1에 두고, 창고 2에서 모터 세트(16번)를 새로 시작",
            17: "📦 창고 2의 세트(16번)는 그대로 두고, 창고 3에서 판+블록 세트(17번)를 새로 시작",
            18: "창고 3의 세트(17번)를 가져와 창고 2의 16번과 합쳐요 — 번호표 '16 + 17'",
            21: "📦 창고 2의 세트(20번)는 그대로 두고, 창고 3에서 큰기어 세트(21번)를 새로 시작",
            23: "창고 3의 세트(22번)를 가져와 창고 2의 20번과 합쳐요 — 번호표 '20 + 22'",
            24: "📦 창고 2의 세트(23번)는 그대로 두고, 창고 3에서 회색 판+블록 세트(24번)를 새로 시작",
            26: "창고 3의 세트(25번)를 가져와 창고 2의 23번과 합쳐요 — 번호표 '23 + 25'",
            27: "📦 창고 2의 세트(26번)는 그대로 두고, 창고 3에서 큰기어+검은 판 세트(27번)를 새로 시작",
            30: "창고 3의 세트(29번)를 가져와 창고 2의 26번과 합쳐요 — 번호표 '26 + 29'",
            32: "📦 창고 2의 세트(31번)는 그대로 두고, 창고 3에서 회색 판+블록 세트(32번)를 새로 시작",
            33: "창고 3의 세트(32번)를 가져와 창고 2의 31번과 합쳐요 — 번호표 '31 + 32'",
            34: "창고 2의 세트(33번)를 가져와 창고 1의 15번 세트와 합쳐요 — 번호표 '15 + 33', 번호가 작은 창고 1 에서 합친다"}
for _i, _h in _HIST_BW.items(): A.steps[_i - 1].kw["history"] = _h


# ── 1 ── 교재 100쪽 1 (읽은 것 2026-10-25 — 713프레임(7줄×13칸) 둘을 줄 방향으로 이어 붙이고(가까운 판 줄1 ↔ 먼 판 줄7 이 맞닿음) 그 이음매 위에 29프레임(2줄×9칸)을 얹어 리벳 넷과 8볼트·너트 둘로 잇는다)
#   책 1번 홀라인(가까운 713프레임): holefit 어두운판 56/91구멍 평균 0.62px → axes_fit 오차 0.45px(91점) θ −0.49 φ 1.03. 링: 리벳 = 가까운 판 칸5·칸13 줄1(그림 아래 판), 먼 판은 같은 칸 줄7(이음매 쪽); 볼트 = 칸9(29프레임 가운데 구멍)
#   방향: 칸 → +X, 줄 → +Z(가까운 판 줄1 z +5, 먼 판 줄7 z −5). 29프레임 구멍 칸1~9 ↔ 판 칸5~13(x −40~+40), 가운데 칸5 ↔ 판 칸9 = x 0. 볼트 머리는 판 아래, 너트는 29프레임 위(책 "볼트/너트 방향 주의").
s1 = SKEL[0]; s1.kw.pop("noPart", None)
s1.note = "[교재 1] 713프레임 둘을 이어 붙이고 이음매 위에 29프레임을 얹어 리벳 넷·볼트 둘·너트 둘로 이어요."
PF1 = s1.place("713프레임", np.eye(3), (-20.0, 2.5, -35.0))   # 먼 판: 줄7 z −5(이음매) … 줄1 z −65, 칸c x = −20+(c−7)·10
PN1 = s1.place("713프레임", np.eye(3), (-20.0, 2.5, 35.0))    # 가까운 판: 줄1 z +5(이음매) … 줄7 z +65
R_BOLT_UP = np.diag([1.0, -1.0, -1.0])   # 볼트·너트: 돌기가 +Y 를 본다(머리·몸이 판 아래/위)
RV1 = [s1.attach("리벳", np.eye(3), {"p1": (_pl, "h%d_%d" % (_c, _r))}, rivet=True, hover=25, dir=[0, 1, 0]) for _pl, _r in ((PF1, 7), (PN1, 1)) for _c in (5, 13)]   # 판 칸5·13 이음매 쪽 줄 — 결합 전(분리)
PA1 = s1.recv("29프레임", np.eye(3), {"h1_1": (RV1[0], "p2"), "h1_2": (RV1[2], "p2"), "h9_1": (RV1[1], "p2"), "h9_2": (RV1[3], "p2")}, dir=[0, 1, 0], hover=50)   # 줄1(z −5) = 먼 판 리벳, 줄2(z +5) = 가까운 판 리벳
BT1 = [s1.attach("8볼트", R_BOLT_UP, {"p1": (_pl, "h9_%d" % _r)}, hover=45, dir=[0, -1, 0]) for _pl, _r in ((PF1, 7), (PN1, 1))]   # 칸9 이음매 쪽 줄, 머리가 판 아래
NT1 = [s1.attach("너트", R_BOLT_UP, {"p1": (PA1, "h5_%d" % _r)}, hover=90, dir=[0, 1, 0]) for _r in (1, 2)]   # 29프레임 칸5 구멍 위(몸이 위) — 띄움은 29프레임(50)보다 위(90)로 책처럼 맨 위에서 내려오게
A.steps[0].cam = (-0.49, 1.03, False, None, None, None); A.steps[0].camSrc = "eye"   # holefit 가까운 713프레임 → axes_fit 오차 0.45px(91점, roll 0.5°)
A.meta["lift"] = {"1": 50.0}   # 볼트가 판 아래로 내려오는 번호 — 화면을 올림

import stepchecks; stepchecks.apply(A, "bowling")
# ── 2 ── 교재 100쪽 2 (읽은 것 2026-10-25 — 이어 붙인 바닥(13칸×14줄) 먼 쪽 줄2·가까운 쪽 줄13(큰 줄 번호)에 흰 19프레임 막대 둘을 리벳 둘씩(칸3·11)으로 이어 얹는다)
#   책 2번 홀라인(바닥 13×14): holefit DoG 103개 평균 0.79px → axes_fit 1.15px(182점) θ −0.47 φ 0.73. 29프레임 칸5~13 줄7·8(이음매), 볼트·너트 칸9. 새 리벳 링 4 = 칸3·11 × 줄2(먼 판 줄2)·줄13(가까운 판 줄6), 막대 구멍1·9번이 리벳 위.
#   큰 줄 r ≤ 7 = 먼 판 줄 r, r ≥ 8 = 가까운 판 줄 r−7. 막대 길이(9칸) = 칸3~11, 가운데 칸7 = x −20.
s2 = SKEL[1]; s2.kw.pop("noPart", None)
s2.note = "[교재 2] 바닥 앞·뒤 가장자리 쪽(줄2·줄13)에 흰 19프레임 막대 둘을 리벳 둘씩(칸3·11)으로 이어요."
RV2 = []; BR2 = []
for _pl, _r in ((PF1, 2), (PN1, 6)):   # 먼 판 줄2(z −55) · 가까운 판 줄6(큰 줄 13, z +55)
    _rv = [s2.attach("리벳", np.eye(3), {"p1": (_pl, "h%d_%d" % (_c, _r))}, rivet=True, hover=25, dir=[0, 1, 0]) for _c in (3, 11)]   # 결합 전(분리)
    RV2 += _rv
    BR2.append(s2.recv("19프레임", np.eye(3), {"h1_1": (_rv[0], "p2"), "h9_1": (_rv[1], "p2")}, dir=[0, 1, 0], hover=50))
A.steps[1].cam = (-0.47, 0.73, False, None, None, None); A.steps[1].camSrc = "eye"   # holefit 바닥 13×14 → axes_fit 오차 1.15px(182점, roll 0.3°)


# ── 3 ── 교재 101쪽 3 (읽은 것 2026-10-25 — "2 ↷ 뒤집기": 1~2번 바닥을 가로축(X) 둘레로 뒤집어 29프레임·막대가 달린 면이 아래로 가게 한다. 그 아래 면에 흰 59프레임(5줄×9칸)이 바닥 왼쪽 끝(칸1·2 쪽)에서 밖으로 뻗게 리벳 둘(칸1 줄5·9)·8볼트 둘·너트 둘(칸2 줄5·9)로 붙는다)
#   책 3번 홀라인(뒤집은 바닥 13×14, 보이는 면 = 원래 아랫면): holefit DoG 138개 평균 1.31px → axes_fit 1.98px(182점) θ −0.72 φ 1.13. 보이는 면에 주황 리벳 8개·회색 볼트 머리 둘이 보인다(2번까지의 리벳 4+4, 볼트 2 — via 2→3).
#   링: 리벳 = 보이는 격자 칸1 줄5·줄9, 볼트 = 칸2 줄5·줄9 → 뒤집었으니 모델 판 줄로는 가까운 판 줄3(z' −25)·먼 판 줄6(z' +15). 흰 판 칸8(리벳)·칸9(볼트) 가 바닥 칸1·2 아래, 흰 판 줄1·5(4줄 간격) = 링 둘.
s3 = SKEL[2]; s3.kw.pop("noPart", None)
s3.note = "[교재 3] 1~2번 바닥을 뒤집어(가로축) 흰 59프레임을 아래 면 왼쪽 끝에 리벳 둘·볼트 둘·너트 둘로 붙여요."
_G3 = A.group("바닥(1~2번)", [_q for _q in A.parts if _q.step.index <= 2])
_mk3 = {id(PN1): [[-80.0, 0.0, -25.0], [-70.0, 0.0, -25.0]], id(PF1): [[-80.0, 0.0, 15.0], [-70.0, 0.0, 15.0]]}   # 초록·노랑 링 = 바닥 아래 면 구멍 입구(칸1 리벳·칸2 볼트)
s3.move_made(_G3, np.diag([1.0, -1.0, -1.0]), pivot=(-20.0, 2.5, 0.0), shift=(0.0, 0.0, 0.0), dir=[0, 1, 0], hover=50, marks=_mk3)   # 2 ↷ 뒤집기: 가로축 둘레 180°(y → 5−y, z → −z)
WP3 = s3.place_next("59프레임", np.eye(3), "h8_1", PN1, "h1_3", (0.0, -5.0, 0.0))   # 흰 판: 칸8 x −80·칸9 x −70(바닥 칸1·2 아래), 줄1 z' −25 … 줄5 z' +15, 윗면이 바닥 아랫면(y 0)에 닿음
RV3 = [s3.attach("리벳", np.eye(3), {"p1": (WP3, "h8_%d" % _r)}, rivet=True, hover=25, dir=[0, 1, 0]) for _r in (1, 5)]   # 결합 전(분리)
BT3 = [s3.attach("8볼트", np.eye(3), {"p1": (_pl, _h)}, hover=100, dir=[0, 1, 0]) for _pl, _h in ((PN1, "h2_3"), (PF1, "h2_6"))]   # 머리가 바닥 윗면(원래 아랫면)에, 돌기가 아래로 — 띄움은 바닥 묶음(50)보다 위(100)로 위에서 내려오게
NT3 = [s3.attach("너트", np.eye(3), {"p1": (WP3, "h9_%d" % _r)}, hover=40, dir=[0, -1, 0]) for _r in (1, 5)]   # 흰 판 아래에서
A.steps[2].cam = (-0.72, 1.13, False, None, None, None); A.steps[2].camSrc = "eye"   # holefit 뒤집은 바닥 13×14 → axes_fit 오차 1.98px(182점, roll 1.2°)
