for _br in BR10:   # 브라켓마다 세로 팔 위 줄 구멍 h7(x −5)·h8(x +5)
    RV11.append([s11.attach("리벳", R_RIV_Z, {"p1": (_br, _h)}, rivet=True, hover=0.01, dir=[0, 0, 1]) for _h in ("h3", "h4")])   # 안쪽(+Z)에서 세로 팔 구멍으로 — 결합 전
PR11 = s11.recv("215프레임", R_RAIL, {"h1_2": (RV11[0][1], "p2"), "h2_2": (RV11[0][0], "p2"), "h14_2": (RV11[1][1], "p2"), "h15_2": (RV11[1][0], "p2")}, dir=[0, 0, 1], hover=82)   # 위 줄(줄2) 구멍1·2 = 검은 판 쪽 브라켓, 14·15 = 흰 판 쪽 브라켓
A.steps[10].cam = (0.55, 0.95, False, None, None, None); A.steps[10].camSrc = "eye"   # 흰 판 holefit + 검은 판 앵커 합친 카메라 → axes_fit θ 0.55 φ 0.95(roll 2.1°)

# ── 12 ── 교재 102쪽 12 "6 + 11" (읽은 것 2026-10-25 — 창고 2 의 11번 조립(뒤집은 레인+브라켓 둘+215프레임, 7~11번 부품)을 창고 1 의 6번 몸 위쪽 벽 끝 3단블록에 끼운다: 레인 3단블록(9번, 칸5~7 줄3)의 판 반대 면 돌기 p7·p6·p8 이 벽 끝 3단블록(4번 판 끝 블록, 먼 벽 z −45)의 구멍 h1·h2·h3 에 들어간다. 레인은 책에서 위로 떠 있다가 비스듬히(약 50°) 선 채 내려온다)
#   책 12번 홀라인(6번과 같은 몸 바닥 13×14, 보이는 면): holefit 어두운판 62구멍 평균 0.51px(34% — 벽·블록에 가려 기준 40% 미달) → 리벳 끝 6곳(칸 3·2, 1·9, 3·13, 13·7, 13·8, 11·13 — 6번과 같은 바닥 리벳, 격자에서 정수 칸 ±0.2)을 앵커로 infer_grid(구멍 62개 평균 1.12px·최대 2.39px, 2등과 비 1.97) → axes_fit θ 0.88 φ 0.80(roll 0.8°). 링 2개 = 벽 끝 3단블록 구멍(바깥 둘 h1·h3).
#   결합 방향: 벽 끝 블록 구멍 줄 h1→h3 = (0.76, −0.65, 0), 구멍 축(열린 쪽) = (0.65, 0.76, 0) — 레인 블록 돌기 줄(레인 +x)이 구멍 줄과 같은 방향, 돌기 방향(레인 −y, 뒤집은 레인에서 아래)이 구멍 열린 쪽의 반대. 그러면 레인 +x(흰 판 끝)가 오른쪽 아래, 보이는 면(레인 +y)이 위 오른쪽(+0.65, +0.76), 레인 폭(줄 z)은 세계 +Z 가 된다 — 책 12번에서 흰 판이 아래, 검은 판이 위인 것과 같다.
s12 = SKEL[11]; s12.kw.pop("noPart", None)
s12.note = "[교재 12] 창고 2 의 11번 조립(뒤집은 레인+브라켓+215프레임)을 6번 몸 위쪽 벽 끝 3단블록에 비스듬히 끼워요(6 + 11)."
G12 = A.group("레인 조립(7~11번)", [_q for _q in A.parts if 7 <= _q.step.index <= 11])
_WB12 = BL4[0][3]   # 먼 쪽 벽(z −45)의 끝 3단블록(4번 판 끝 블록, 6번에서 벽과 함께 세워진 자세)
_hw = {_h["id"]: np.array(_WB12.world("hole", _h)["pos"], float) for _h in _WB12.conn["holes"]}
_dh = np.array(_WB12.world("hole", next(_h for _h in _WB12.conn["holes"] if _h["id"] == "h1"))["dir"], float); _dh /= np.linalg.norm(_dh)   # 구멍 축(열린 쪽 쪽)
_aw = _hw["h3"] - _hw["h1"]; _aw /= np.linalg.norm(_aw)
R_T12 = np.column_stack([_aw, _dh, np.cross(_aw, _dh)])   # 레인 +x → 구멍 줄, 레인 +y(보이는 면) → 구멍 열린 쪽, 레인 +z → 두 벡터의 외적
_pg = {_q["id"]: np.array(BL9.world("peg", _q)["pos"], float) for _q in BL9.conn["pegs"]}
_pv12 = _pg["p6"].copy()
_sh12 = (_hw["h2"] + 2.5 * _dh) - _pv12   # 가운데 돌기 p6 가 가운데 구멍 h2 의 입구에서 2.5(돌기 길이 5 의 절반) 안쪽에 오게
_mk12 = {id(BL9): [[float(_v) for _v in (_hw[_k] + 5.0 * _dh)] for _k in ("h1", "h3")]}   # 초록 링 = 벽 끝 블록 구멍 h1·h3 입구
s12.move_made(G12, R_T12, pivot=tuple(float(_v) for _v in _pv12), shift=tuple(float(_v) for _v in _sh12), dir=[float(_v) for _v in _dh], hover=60, group="mm12lane", marks=_mk12)   # 6 + 11
A.steps[11].cam = (0.88, 0.80, False, None, None, None); A.steps[11].camSrc = "eye"   # holefit 몸 바닥 13×14 + 리벳 앵커 6곳 infer_grid → axes_fit 0.88/0.80(roll 0.8°)
for _i in range(12, 38): A.meta["lift"][str(_i)] = 5.0   # 12번에서 레인이 비스듬히 서 흰 판 끝이 바닥에 닿는다(가장 낮은 곳 y 0.7) — 뒤집은 레인용 올림(11번)은 12번부터 필요 없다

